  [1324315] = { "Permette al $N1% della rigenerazione del mana di continuare durante il lancio di incantesimi.", "Permette di mantenere il $N1% della rigenerazione del mana durante il lancio di incantesimi.", 0x86815c0c, 0x301e5adc, "uu" },
  [1324318] = { "Gli incantesimi che infliggono danni possono permettere al $N1% della tua rigenerazione del mana di continuare durante il lancio per $D1. Questa ⟦Mana Regeneration=Rigenerazione del Mana⟧ raddoppia nelle roccaforti e nelle città.", nil, 0x06542bbb, nil, "um" },
