  [1324401] = { nil, "Silenziato.", nil, 0x20816e34, "mu" },
  [1324415] = { "Incatena il bersaglio nemico non morto per un massimo di $D1. L'unità incatenata non può muoversi, attaccare o lanciare incantesimi. Eventuali danni inflitti liberano il bersaglio. Può essere incatenato solo un bersaglio alla volta.", "Incatenato.", 0xe3712b94, 0xa9a81857, "uu" },
  [1324420] = { "Incatena il bersaglio nemico non morto per un massimo di $D1. L'unità incatenata non può muoversi, attaccare o lanciare incantesimi. Eventuali danni inflitti liberano il bersaglio. Può essere incatenato solo un bersaglio alla volta.", "Incatenato.", 0xe3712b95, 0xa9a81858, "uu" },
  [1324422] = { "Incatena il bersaglio nemico non morto per un massimo di $D1. L'unità incatenata non può muoversi, attaccare o lanciare incantesimi. Eventuali danni inflitti liberano il bersaglio. Può essere incatenato solo un bersaglio alla volta.", "Incatenato.", 0xd5f2a9c8, 0x440dd100, "uu" },
  [1324427] = { "Silenzia il bersaglio, impedendogli di lanciare incantesimi per $D1 e interrompendo i suoi incantesimi in corso per $D2.", "Silenziato.", 0xd69ce02d, 0x44b80765, "uu" },
  [1324448] = { "Incute paura al nemico, costringendolo a fuggire per un massimo di $D1. Eventuali danni inflitti al bersaglio potrebbero interrompere l'effetto. Può essere spaventato solo $N2 bersaglio alla volta.", "Impaurito.", 0xe2e8be41, 0xa91fab04, "uu" },
  [1324451] = { "Incute paura al nemico, costringendolo a fuggire per un massimo di $D1. Eventuali danni inflitti al bersaglio potrebbero interrompere l'effetto. Può essere spaventato solo $N2 bersaglio alla volta.", "Impaurito.", 0xe309b91b, 0xa940a5de, "uu" },
  [1324453] = { "Incute paura al nemico, costringendolo a fuggire per un massimo di $D1. Eventuali danni inflitti al bersaglio potrebbero interrompere l'effetto. Può essere spaventato solo $N2 bersaglio alla volta.", "Impaurito.", 0xe309b91d, 0xa940a5e0, "uu" },
  [1324459] = { "Fa fuggire in preda all'orrore il nemico bersaglio per $D1 e gli infligge $N2 danni da ombra. L'incantatore guadagna in salute il $N3% dei danni inflitti.", "Terrorizzato.", 0xe30b0be3, 0xa941f8a6, "uu" },
  [1324462] = { "Esilia il nemico bersaglio, impedendogli di compiere qualsiasi azione ma rendendolo invulnerabile per un massimo di $D1. Può essere esiliato solo un bersaglio alla volta. Funziona solo su demoni ed elementali.", "Invulnerabile, ma impossibilitato ad agire.", 0x59ac4db2, 0xe2069da9, "uu" },
  [1324463] = { "Esilia il nemico bersaglio, impedendogli di compiere qualsiasi azione ma rendendolo invulnerabile per un massimo di $D1. Può essere esiliato solo un bersaglio alla volta. Funziona solo su demoni ed elementali.", "Invulnerabile, ma impossibilitato ad agire.", 0xd7044d04, 0x451f743c, "uu" },
  [1324468] = { "Soggioga il demone bersaglio, fino al livello $N1, costringendolo a eseguire i tuoi ordini. Mentre è soggiogato, l'intervallo tra gli attacchi del demone aumenta del $N2% e la sua velocità di lancio d'incantesimi si riduce del $N3%. Dura fino a $D1. Se soggioghi ripetutamente lo stesso demone, diventerà più difficile da controllare a ogni tentativo.", "Assoggettato.", 0xe25db31f, 0xa8949fe2, "uu" },
  [1324473] = { "Affligge il bersaglio per $D1: il $N2% di tutti i danni inflitti dallo Stregone ad altri bersagli viene inflitto anche al bersaglio maledetto. Esilio della Calamità è limitato a $N3 bersaglio e ogni Stregone può avere un solo anatema attivo su uno stesso bersaglio.", "Subisci il $N1% di tutti i danni che lo Stregone infligge ad altri bersagli.", 0x842053dd, 0x7e579dd1, "uu" },
  [1324474] = { { "Mossa risolutiva che stordisce il bersaglio. La durata aumenta con i punti combo:\n $N1 punto: $N2 s\n $N3 punti: $N4 s\n $N5 punti: $N6 s\n $N7 punti: $N8 s\n $N9 punti: $N10 s", shape = { "10/0" } }, { "Mossa risolutiva che stordisce il bersaglio. La durata aumenta con i punti combo:\n $N1 punto: $N2 s\n $N3 punti: $N4 s\n $N5 punti: $N6 s\n $N7 punti: $N8 s\n $N9 punti: $N10 s", shape = { "10/0" } }, 0x3a9d69b5, 0x3a9d69b5, "uu" },
  [1324475] = { "Mossa risolutiva che stordisce il bersaglio. La durata aumenta con i punti combo:\n $N1 punto: $N2 s\n $N3 punti: $N4 s\n $N5 punti: $N6 s\n $N7 punti: $N8 s\n $N9 punti: $N10 s", { "Stordito e danni subiti dal Ladro aumentati del $N1%.", "Stordito.", shape = { "1/0", "0/0" } }, 0xe34f61fe, 0xa9864ec1, "uu" },
  [1324477] = { "Acceca il bersaglio, costringendolo a vagare disorientato per un massimo di $D1. Eventuali danni inflitti interrompono l'effetto.", "Disorientato.", 0xe28000b6, 0xa8b6ed79, "uu" },
  [1324481] = { { "Infligge $N1 danni, interrompe il tuo attacco e inabilita il bersaglio per $D1. Il bersaglio deve essere rivolto verso di te. Qualsiasi danno subito interrompe l'effetto. Fornisce $N3 punti combo.", shape = { "3/1" } }, { "Infligge $N1 danni, interrompe il tuo attacco e inabilita il bersaglio per $D1. Il bersaglio deve essere rivolto verso di te. Qualsiasi danno subito interrompe l'effetto. Fornisce $N3 punti combo.", shape = { "3/1" } }, 0x4a261ddb, 0x4a261ddb, "uu" },
  [1324482] = { "Inabilita il bersaglio per un massimo di $D1. Funziona solo sugli umanoidi non in combattimento. Qualsiasi danno subito interrompe l'effetto. Puoi tenere tramortiti al massimo $N2 bersagli alla volta. Non interrompe la Furtività.", "Inabilitato.", 0xe30b0b57, 0xa941f81a, "uu" },
